🐛 Describe the bug
After linalg_cholesky decomposition, the tensor changes from row major to clo major!
The code is as follows:
#include <torch/torch.h>
#include <iostream>

void PrintTensorMemory(torch::Tensor& A)
{
    auto len = A.reshape({-1}).size(0);
    auto p = A.data_ptr<float>();
    for (int loop = 0; loop < len; loop++)
        printf("(%.4f)", *(p+loop));
    printf("\n");
}

int main() {
    int num = 4;
    printf("*==================================================\n");
    auto A = torch::randn({num, num}, torch::kFloat);
    auto B = torch::matmul(A, A.mT());
    B += torch::eye(num, torch::kFloat);
    std::cout << B << std::endl;
    PrintTensorMemory(B);
    auto C = torch::linalg_cholesky(B);
    std::cout << C << std::endl;
    PrintTensorMemory(C);
    return 0;
}

The output is as follows:
